using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class MargueriteYourcenar
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "On n'est jamais tout à fait seul : par malheur, on est toujours avec soi-même.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Un grossissement de plus, et ces visages se décomposeraient en mouvements d'atomes, aussi indifférents à ce baiser que nous pouvons l'être aux amours démesurées des astres.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "La lettre écrite m'a enseigné à écouter la voix humaine, tout comme les grandes attitudes immobiles des statues m'ont appris à apprécier les gestes.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "L'une des meilleures manières de recréer la pensée d'un homme : reconstituer sa bibliothèque.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Faire de son mieux. Refaire. Retoucher imperceptiblement encore cette retouche. « C’est moi-même que je corrige, disait Yeats, en retouchant mes œuvres. »", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Qui serait assez insensé pour mourir sans avoir fait au moins le tour de sa prison ?", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "(…) je m’arrête, prise de vertige devant l’inextricable enchevêtrement d’incidents et de circonstances qui plus ou moins nous déterminent tous.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Le fait reste que, même pour les moins gourmets, les moins gourmands ou les moins goinfres, vivre ensemble, c’est en partie manger ensemble.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Pendant ce temps, la terre tournait.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "J’avais l’imperceptible recul du chien qui détourne le cou quand on lui présente un collier.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Cette femme assurément douée d’agréments (…)", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Ce qui surnage comme toujours, c’est l’infinie pitié pour le peu que nous sommes, et, contradictoirement, le respect et la curiosité de ces fragiles et complexes structures, posées comme sur pilotis à la surface de l’abîme, et dont aucune n’est tout à fait pareille à aucune autre.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Comme toujours, chaque fois qu’il se tourne vers le monde extérieur, la vie est là, avec son imprévu, sa foncière tristesse, sa décevante douceur, et sa presque insupportable plénitude.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il se souvient d’avoir écrit quelque part qu’il n’y avait devant la vie et la mort que deux attitudes valables, le christianisme et le stoïcisme.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "(…) cette époque qui nous semble à distance épaisse et inerte, suspendue comme un énorme remblai au bord de l’abîme du XXè siècle.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Mon visage commence à se dessiner sur l’écran du temps.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "C'est par l'effet de notre arrogance, qui sans cesse refuse aux hommes du passé des perceptions pareilles aux nôtres, que nous dédaignons de voir dans les fresques des cavernes autre chose que les produits d'une magie utilitaire : les rapports entre l'homme et la bête, d'une part, entre l'homme de son art, de l'autre, sont plus complexes et vont plus loin.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Nos livres d'école nous ressassaient que ces Gaulois au grand cœur ne craignaient rien, sinon que le ciel ne tombât. Plus courageux ou plus désespérés qu'ils ne l'étaient, nous avons pris l'habitude, depuis 1945, de nous attendre à voir le ciel tomber.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Tout a déjà été éprouvé et expérimenté à mille reprises, mais souvent sans avoir été dit, ou sans que les paroles qui le disaient subsistent, ou, si elles le font, nous soient intelligibles ou nous émeuvent encore. Comme les nuages dans le ciel vide, nous nous formons et nous dissipons sur ce fond d'oubli.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "S'il est question de tout un ensemble de transmissions plus inanalysables, c'est de la terre entière que nous sommes les légataires universels. Un poète ou un sculpteur grec, un moraliste romain né en Espagne, un peintre issu d'un notaire florentin et d'une servante d'auberge dans un village des Apennins, un essayiste périgourdin sorti d'une mère juive, un romancier russe ou un dramaturge scandinave, un sage hindou ou chinois nous ont peut-être davantage formés que ces hommes et ces femmes dont nous avons été l'un des descendants possibles, un de ces germes dont des milliards se perdent sans fructifier dans les cavernes du corps ou entre les draps des époux.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "De temps en temps, comme un cortège passant dans une rue tranquille jette les reflets de ses torches sur les vitres d'une maison endormie, et les fait tressaillir du bruit de ses tambours et de ses fifres, l'histoire ainsi projette ses feux sur une famille à peu près sans histoire.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Dans le fallacieux combat entre l'ordre et la justice, Michel Charles s'est déjà rangé du côté de l'ordre. Il croira toute sa vie qu'un homme bien né, bien élevé, bien lavé, bien nourri et bien abreuvé sans excès, cultivé comme il convient qu'un homme de bonne compagnie le soit de son temps, est non seulement supérieur aux misérables, mais encore d'une autre race, presque d'un autre sang. Même s'il se rencontrait, parmi beaucoup d'erreurs, une petite parcelle de vérité dans cette vue qui, avouée ou tacite, a été celle de toutes les civilisations jusqu'à nos jours, ce qu'elle contient de faux finit toujours par lézarder toute société qui se repose sur elle. Au cours de son existence d'homme privilégié, mais pas nécessairement d'homme heureux, Michel Charles n'a jamais traversé de crise assez forte pour s'apercevoir qu'il était en dernière analyse le semblable de ces rebuts humains, peut-être leur frère. Il ne s'avouera pas non plus que tout homme, un jour ou l'autre, se voit condamné aux travaux forcés à perpétuité.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "C'est toujours un moment grave que celui où un jeune esprit jusque là insoucieux de politique découvre soudain que l'injustice et l'intérêt mal entendu passent et repassent devant lui dans les rues d'une ville avec des effets de cape et d'uniforme, ou s'attablent au café sous l'aspect de bons bourgeois qui ne prennent pas parti.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Néanmoins, à une époque où chacun ment ou déraisonne, où on n'a le choix qu'entre les défenseurs de l'ordre durcis dans leur moralité d'apparat sans pitié ni bonté et des idéologues amenant à force de gaffes l'heure des dictatures, entre les loups bien nourris d'une part et les moutons enragés de l'autre, le jeune homme qui s'amuse à fabriquer un presse-papiers avec des fragments de marbre est peut-être un réaliste.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "À la vérité, toutes les sociétés, quelles qu'elles soient, sont basées sur la possession des choses ; une bonne partie des gens qui se font peindre ont toujours exigé qu'on mît près d'eux leurs bibelots favoris, tout comme aux temps antiques ils auraient demandé qu'on les plaçât dans leurs tombes.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Pour ces pharisiens qui se croient des chrétiens, aimer autrui comme soi-même est un de ces préceptes qui font du bien quand le curé les débite en chaire ; ceux qui ont faim et soif de la justice sont des émeutiers qui finissent au bagne.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Les yeux de l'enfant et ceux du vieillard regardent avec la tranquille candeur de qui n'est pas encore entré dans le bal masqué ou en est déjà sorti. Et tout l'intervalle semble un tumulte vain, une agitation à vide, un chaos inutile par lequel on se demande pourquoi on a dû passer.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Cette porte entrouverte donne à la fois sur la plus concrète réalité et sur le plus fuyant des mystères, qui est le temps. L’éternité n’est sans doute que la même chose autrement, mais les rapports que nous entretenons avec ces deux notions sont à la fois infiniment rapprochées et à jamais susceptibles d’une solution adéquate, comme ceux du diamètre d’un cercle avec sa circonférence.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il est beau d’espérer que sous une forme ou sous une autre, que la plupart des religions ont choisie féminine, comme Marie, ou androgyne comme Kwannon, la douceur et la compassion nous accompagneront, peut-être invisiblement à l’heure de notre mort.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il subsistait sans livres, n’ayant trouvé dans la maisonnette qu’une Bible qu’il brûla par poignées un jour où le poêle prenait mal. Mais il lui semblait maintenant que les livres qu’il lui était arrivé de lire (fallait-il juger d’après eux tous les livres ?) lui avaient fourni peu de chose, moins peut-être que l’enthousiasme ou la réflexion qu’il leur avait apportés; il pensait en tout cas qu’il eût été mal de ne pas s’absorber exclusivement dans la lecture du monde qu’il avait, maintenant et pour si peu de temps, sous les yeux et qui, pour ainsi dire, lui était échu en lot. Lire des livres, comme lamper de l’eau-de-vie, eût été une manière de s’étourdir pour ne pas être là. Et d’ailleurs, qu’étaient les livres ?", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Reste […], aussi indépendant que possible de toute opinion inculquée, le quasi autodidacte nullement simple, mais délesté à l’extrême, se méfiant instinctivement de ce que les livres qu’il feuillette, les musiques qu'il lui arrive d'entendre, les peintures sur lesquelles se posent parfois ses yeux ajoutent à la nudité des choses, indifférent aux grands événements des gazettes, sans préjugé dans tout ce qui touche à la vie des sens, mais aussi sans l’excitation ou les obsessions factices qui sont l’effet de la contrainte ou d’un érotisme acquis, prenant la science et la philosophie pour ce qu’elles sont, et surtout pour ce que sont les savants et les philosophes qu’il rencontre, et levant sur le monde un regard d’autant plus clair qu’il est plus incapable d’orgueil. Il n’y a rien d’autre à dire sur Nathanaël.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il y a deux sortes d'êtres humains : ceux qui écartent la mort de leur pensée pour mieux et plus librement vivre, et ceux qui, au contraire, se sentent d'autant plus sagement et fortement exister qu'ils la guettent dans chacun des signaux qu'elle leur fait à travers les sensations de leur corps ou les hasards du monde extérieur. Ces deux sortes d'esprits ne s'amalgament pas. Ce que les uns appellent une manie morbide est pour les autres une héroïque discipline. C'est au lecteur à se faire une opinion.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Quoi qu'il arrive, j'apprends. Je gagne à tout coup.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "On ne voit pas deux fois le même cerisier, ni la même lune découpant un pin. Tout moment est dernier, parce qu'il est unique. Chez le voyageur cette perception s'aiguise par l'absence des routines fallacieusement rassurantes propres au sédentaire, qui font croire que l'existence pour un temps restera ce qu'elle est.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Solitude… Je ne crois pas comme ils croient, je ne vis pas comme ils vivent, je n’aime pas comme ils aiment… Je mourrai comme ils meurent.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "L'alcool dégrise. Après quelques gorgées de cognac, je ne pense plus à toi.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il n’y a pas d’amour malheureux : on ne possède que ce qu’on ne possède pas. Il n’y a pas d’amour heureux : ce qu’on possède, on ne le possède plus.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Rien à craindre. J’ai touché le fond. Je ne puis tomber plus bas que ton cœur.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Un cœur, c'est peut-être malpropre. C'est de l’ordre de la table d’anatomie et de l’étal de boucher. Je préfère ton corps.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Rien de plus sale que l'amour-propre.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Je me refuse à faire de toi un objet, même quand ce serait l'Objet Aimé.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Aimer les yeux fermés, c’est aimer comme un aveugle. Aimer les yeux ouverts, c’est peut-être aimer comme un fou : c’est éperdument accepter. Je t’aime comme une folle.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "On arrive vierge à tous les événements de sa vie. J’ai peur de ne pas savoir m’y prendre avec ma Douleur.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Brûlé de plus de feux… Bête fatiguée, un fouet de flammes me cingle les reins. J’ai retrouvé le vrai sens des métaphores de poètes. Je me réveille chaque nuit dans l’incendie de mon propre sang.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Je ne tomberais pas. J’ai atteint le centre. J’écoute le battement d’on ne sait quelle divine horloge à travers la mince cloison charnelle de la vie pleine de sang, de tressaillements et de souffles. Je suis près du noyau mystérieux des choses comme la nuit on est quelquefois près du cœur.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Quand je te revois, tout redevient limpide. J’accepte de souffrir.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Et tu t’en vas ? Tu t’en vas ?… Non, tu ne t’en vas pas : je te garde. Tu me laisses dans les mains ton âme comme un manteau.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "On dit : fou de joie. On devrait dire : sage de douleur.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il y’a six jours, il y’a six mois, il y eu six ans, il y aura six siècles… Ah ! mourir pour arrêter le temps…", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "L’amour est un châtiment. Nous sommes punis de n’avoir pas pu rester seuls.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Je ne puis m’empêcher de voir dans mon amour une forme raffinée de la débauche, un stratagème pour passer le temps, pour se passer du Temps. Le plaisir effectue en plein ciel un atterrissage forcé, dans le bruit de moteur fou des derniers soubresauts du cœur. En vol plané, la prière y monte ; l’âme y entraîne le corps dans l’assomption de l’amour. Pour qu’une assomption soit possible, il faut un Dieu. Tu as juste assez de beauté, d’aveuglement et d’exigences pour figurer un tout-puissant. J’ai fait de toi faute de mieux la clef de voûte de mon univers.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Tes cheveux, tes mains, ton sourire rappellent de loin quelqu’un que j’adore. Qui donc ? Toi-même.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Qu'il eût été fade d'être heureux !", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "L'amour partagé, il faudrait toujours juger sur quel point il l'est et à quel degré. Par exemple, est-ce que Hugo a aimé Juliette comme Juliette a aimé Hugo ? Sûrement pas. Il y a eu peut-être deux ou trois ans d'un amour qui se croyait partagé, et ensuite elle a été l'humble servante du grand homme. On n'a l'impression qu'elle n'a jamais eu, sauf pendant un temps très court, une place de premier rang. Et cela a dû être vrai pour beaucoup de femmes. Pour les hommes, l'amour-abnégation est moins fréquent, parce que l'homme a toujours senti qu'il y avait autre chose dans l'univers et dans la vie qu'un grand amour.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Il y a des vertus spécifiquement « féminines » que les féministes font mine de dédaigner, ce qui ne signifie pas d'ailleurs qu'elles aient été jamais l'apanage de toutes les femmes : la douceur, la bonté, la finesse, la délicatesse, vertus si importantes qu'un homme qui n'en possèderait pas au moins une petite partie serait une brute et non un homme. Il y a des vertus dites « masculines », ce qui ne signifie pas plus que tous les hommes les possèdent : le courage, l'endurance, l'énergie physique, la maîtrise de soi, et la femme qui n'en détient pas au moins une partie n'est qu'un chiffon, pour ne pas dire une chiffe. J'aimerais que ces vertus complémentaires servent également au bien de tous. Mais supprimer les différences qui existent entre les sexes, si variables et si fluides que ces différences sociales et psychologiques puissent être, me paraît déplorable, comme tout ce qui pousse le genre humain, de notre temps, vers une morne uniformité.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Le viol est le crime d'une société qui n'a pas su résoudre, non pas le problème des sexes que celui de la sexualité. Il faudrait que l'enfant apprenne de bonne heure que le coït est un acte sacré, ce qu'ont su les civilisations primitives; que la satisfaction sexuelle dépend en grande partie des rapports de tendresse, de bonne volonté l'un pour l'autre […]. Ce n'est ni par la violence, ni par l'argent, ni même par l'amour fou qu'on parvient à la volupté. Il y faut une compréhension réciproque.", Author = "Marguerite Yourcenar" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "— Je crois d'ailleurs que l'amitié, comme l'amour dont elle participe, demande presqu'autant d'art qu'une figure de danse réussie. Il y faut beaucoup d'élan et beaucoup de retenue, beaucoup d'échanges et de paroles et beaucoup de silences. Et surtout beaucoup de respect.\n— Qu'entendez vous par respect ?\n— Le sentiment de la liberté d'autrui, de la dignité d'autrui, l'acceptation sans illusions, mais aussi sans la moindre hostilité ou le moindre dédain d'un être tel qu'il est. Il y faut aussi (ce qui n'est peut-être pas absolument nécessaire à l'amour, et encore qu'en sais-je ?) une certaine réciprocité.", Author = "Marguerite Yourcenar" },
        };
    }
}